pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        // 1. Keep the domain wide: caller must differ from the initial owner (the deployer, i.e. this contract).
        //    The fuzzer can choose any other address, including address(0).
        vm.assume(caller != address(this));

        // 2. Drive the contract: the caller (not the owner) calls setOwner with a fuzzed newOwner.
        vm.prank(caller);
        bool ok;
        try c.setOwner(newOwner) returns (bool) {
            ok = true;
        } catch {
            ok = false;
        }

        // 3. ASSERTION: For the reference version, ok must be false (revert).
        //    The buggy version (require(true)) succeeds, making ok=true, thus failing this assertion.
        assertTrue(!ok);
    }
}

